import subprocess
def run(s):
    r=subprocess.run(["./executable"], input=(s+"\n").encode('utf-8'), capture_output=True)
    txt=r.stdout.decode()
    nbraille=len(txt.strip())
    last=txt.strip()[-1] if nbraille>0 else None
    if last:
        if ord(last)==0x2809:
            cols=(nbraille-1)*2 + 2
        elif ord(last)==0x2801:
            cols=(nbraille-1)*2 + 1
        else:
            cols=f"?{hex(ord(last))}"
    else:
        cols=0
    return txt, nbraille, cols

tests=["aＨＨ","ＨaＨ","ＨＨa","aaＨ","Ｈaa","aＨa","aＨＨb","ＨaＨa","abＨcd"]
for s in tests:
    txt,nb,cols=run(s)
    print(f"s={s!r} -> {txt!r} nb={nb} cols={cols}")

for s in [" Ｈ","  Ｈ"," ＨＨ","  ＨＨ", " Ｈa", "a Ｈ"]:
    r=subprocess.run(["./executable"], input=(s+"\n").encode(), capture_output=True)
    txt=r.stdout.decode()
    print(f"s={s!r} -> {txt!r} hex={[hex(ord(c)) for c in txt if c!=chr(10)]}")
PY
"}

