import subprocess
def run(s):
    r=subprocess.run(["./executable"], input=(s+"\n").encode('utf-8'), capture_output=True)
    return r.stdout.decode()

for n in [0,1,2,3,4,5,10,20,100]:
    s=" "*n
    out=run(s)
    print(f"nspaces={n} -> {out!r} len={len(out.strip()) if out.strip() else 0}")

for s in ["\u00a0", "\u00a0\u00a0", "\u2000", "\u2000\u2000", "\u3000\u3000"]:
    out=run(s)
    print(f"s={[hex(ord(c)) for c in s]!r} -> {out!r}")

# trailing spaces: "a" + N spaces
for n in [0,1,2,3,10]:
    s="a"+" "*n
    out=run(s)
    print(f"'a'+{n}spaces -> {out!r}")

# leading + trailing?
for s in ["  a  ", " a ", "  aa  "]:
    print(f"{s!r} -> {run(s)!r}")

# test last char byte length vs width: single char of each byte length at end vs start?
# Already did, but test "a" + char vs char + "a" for various byte lengths
for ch in ["é", "中", "😀", "\u2000"]:
    for s in [ch+"a", "a"+ch]:
        out=run(s)
        print(f"s={[hex(ord(c)) for c in s]!r} -> {out!r}")
PY
"}

