use clap::{Arg, ArgAction, Command};
use clap_complete::{generate, Shell};
use std::io;
fn cli() -> Command {
    Command::new("code-minimap")
        .version("0.6.8")
        .about("A high performance code minimap generator")
        .next_line_help(true)
        .disable_version_flag(true)
        .arg(Arg::new("FILE").help("File to read"))
        .arg(Arg::new("HSCALE").short('H').long("horizontal-scale").value_name("HSCALE").help("Specify horizontal scale factor").default_value("1.0"))
        .arg(Arg::new("VSCALE").short('V').long("vertical-scale").value_name("VSCALE").help("Specify vertical scale factor").default_value("1.0"))
        .arg(Arg::new("PADDING").long("padding").value_name("PADDING").help("Specify padding width"))
        .arg(Arg::new("ENCODING").long("encoding").value_name("ENCODING").help("Specify input encoding").default_value("utf8-lossy").value_parser(["utf8-lossy", "utf8"]))
        .arg(Arg::new("version").long("version").action(ArgAction::Version).help("Print version"))
        .subcommand(Command::new("completion").about("Generate shell completion file").arg(Arg::new("SHELL").help("Target shell name").required(true).value_parser(["bash", "elvish", "fish", "powershell", "zsh"])))
}
fn main() {
    let mut cmd = cli();
    for shell in [Shell::Bash, Shell::Elvish, Shell::Fish, Shell::PowerShell, Shell::Zsh] {
        let mut buf = Vec::new();
        generate(shell, &mut cmd, "code-minimap", &mut buf);
        let s = String::from_utf8(buf).unwrap();
        std::fs::write(format!("/tmp/gen_{:?}.txt", shell), s).unwrap();
    }
}
