use clap::{Arg, ArgAction, Command};
use clap_complete::{generate, Shell};
use std::io::{self, Read};
use std::process;

fn cli() -> Command {
    Command::new("code-minimap")
        .version("0.6.8")
        .about("A high performance code minimap generator")
        .next_line_help(true)
        .disable_version_flag(true)
        .arg(Arg::new("FILE").help("File to read"))
        .arg(Arg::new("HSCALE").short('H').long("horizontal-scale").value_name("HSCALE").help("Specify horizontal scale factor").default_value("1.0").value_parser(clap::value_parser!(f64)))
        .arg(Arg::new("VSCALE").short('V').long("vertical-scale").value_name("VSCALE").help("Specify vertical scale factor").default_value("1.0").value_parser(clap::value_parser!(f64)))
        .arg(Arg::new("PADDING").long("padding").value_name("PADDING").help("Specify padding width").value_parser(clap::value_parser!(usize)))
        .arg(Arg::new("ENCODING").long("encoding").value_name("ENCODING").help("Specify input encoding").default_value("utf8-lossy").value_parser(["utf8-lossy", "utf8"]))
        .arg(Arg::new("version").long("version").action(ArgAction::Version).help("Print version"))
        .subcommand(Command::new("completion").about("Generate shell completion file").arg(Arg::new("SHELL").help("Target shell name").required(true).value_parser(["bash", "elvish", "fish", "powershell", "zsh"])))
}

fn is_rust_ws(c: char) -> bool {
    let cp = c as u32;
    (0x09 <= cp && cp <= 0x0D) || cp == 0x20 || cp == 0x85 || cp == 0xA0 || cp == 0x1680 || (0x2000 <= cp && cp <= 0x200A) || cp == 0x2028 || cp == 0x2029 || cp == 0x202F || cp == 0x205F || cp == 0x3000
}

fn main() {
    let matches = cli().get_matches();
    if let Some(sub) = matches.subcommand_matches("completion") {
        let shell = sub.get_one::<String>("SHELL").unwrap().as_str();
        // embedded completions
        let content = match shell {
            "bash" => include_str!("comp_bash.txt"),
            "elvish" => include_str!("comp_elvish.txt"),
            "fish" => include_str!("comp_fish.txt"),
            "powershell" => include_str!("comp_powershell.txt"),
            "zsh" => include_str!("comp_zsh.txt"),
            _ => unreachable!(),
        };
        print!("{}", content);
        return;
    }
    let file = matches.get_one::<String>("FILE");
    let hscale = *matches.get_one::<f64>("HSCALE").unwrap();
    let vscale = *matches.get_one::<f64>("VSCALE").unwrap();
    let padding = matches.get_one::<usize>("PADDING").copied();
    let encoding = matches.get_one::<String>("ENCODING").unwrap().as_str();

    // read input
    let data: Vec<u8> = if let Some(fname) = file {
        match std::fs::read(fname) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("code-minimap: {}", e);
                process::exit(1);
            }
        }
    } else {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).unwrap();
        buf
    };
    // decode
    let s: String = if encoding == "utf8-lossy" {
        String::from_utf8_lossy(&data).into_owned()
    } else {
        match String::from_utf8(data) {
            Ok(v) => v,
            Err(_) => {
                eprintln!("code-minimap: stream did not contain valid UTF-8");
                process::exit(1);
            }
        }
    };
    let out = render(&s, hscale, vscale, padding);
    // write to stdout
    use std::io::Write;
    let stdout = io::stdout();
    let mut handle = stdout.lock();
    handle.write_all(&out).unwrap();
}

struct LineInfo {
    width: usize,
    first: usize,
    is_blank: bool,
}

fn render(s: &str, hscale: f64, vscale: f64, padding: Option<usize>) -> Vec<u8> {
    let lines: Vec<&str> = s.lines().collect();
    let n = lines.len();
    if n == 0 {
        return Vec::new();
    }
    let mut infos: Vec<LineInfo> = Vec::with_capacity(n);
    for line in &lines {
        let mut first: Option<usize> = None;
        let mut last: Option<usize> = None;
        for (idx, ch) in line.char_indices() {
            if !is_rust_ws(ch) {
                if first.is_none() {
                    first = Some(idx);
                }
                last = Some(idx);
            }
        }
        if let (Some(f), Some(l)) = (first, last) {
            infos.push(LineInfo { width: l+1, first: f, is_blank: false });
        } else {
            infos.push(LineInfo { width: 1, first: 0, is_blank: true });
        }
    }
    let eff_v = if vscale > 1.0 { 1.0 } else { vscale };
    let num_scaled: usize = ((n-1) as f64 * eff_v).floor() as usize + 1;
    // group
    let mut groups: Vec<Vec<usize>> = vec![Vec::new(); num_scaled];
    for i in 0..n {
        let j = (i as f64 * eff_v).floor() as usize;
        let j = j.min(num_scaled-1);
        groups[j].push(i);
    }
    // merged rows
    struct Merged { width: usize, first: usize, is_blank: bool }
    let mut merged_rows: Vec<Merged> = Vec::with_capacity(num_scaled);
    for g in &groups {
        let mut min_first: Option<usize> = None;
        let mut max_width: usize = 0;
        let mut has_nonblank = false;
        for &idx in g {
            if !infos[idx].is_blank {
                has_nonblank = true;
                if min_first.is_none() || infos[idx].first < min_first.unwrap() {
                    min_first = Some(infos[idx].first);
                }
                if infos[idx].width > max_width {
                    max_width = infos[idx].width;
                }
            }
        }
        if has_nonblank {
            merged_rows.push(Merged { width: max_width, first: min_first.unwrap(), is_blank: false });
        } else {
            merged_rows.push(Merged { width: 1, first: 0, is_blank: true });
        }
    }
    // horizontal scaling per merged row
    let mut h_rows: Vec<Vec<bool>> = Vec::with_capacity(num_scaled);
    for m in &merged_rows {
        let scaled = (m.width as f64 * hscale) as usize;
        if scaled == 0 {
            h_rows.push(Vec::new());
            continue;
        }
        if m.is_blank {
            h_rows.push(vec![false; scaled]);
            continue;
        }
        let mut row = Vec::with_capacity(scaled);
        for k in 0..scaled {
            let i_start = (k as f64 / hscale) as usize;
            let i_end = ((k+1) as f64 / hscale).ceil() as usize;
            let filled = i_start < m.width && i_end > m.first;
            row.push(filled);
        }
        h_rows.push(row);
    }
    // braille grouping
    let mut out_str = String::new();
    let mut idx = 0;
    while idx < h_rows.len() {
        let chunk_end = (idx+4).min(h_rows.len());
        let chunk = &h_rows[idx..chunk_end];
        let max_w = chunk.iter().map(|r| r.len()).max().unwrap_or(0);
        if max_w == 0 {
            // empty line (0 brailles) + padding?
            if let Some(pad) = padding {
                if 0 < pad {
                    out_str.push_str(&" ".repeat(pad));
                }
            }
            out_str.push('\n');
            idx += 4;
            continue;
        }
        let num_brailles = (max_w+1)/2;
        let mut brailles = String::with_capacity(num_brailles);
        for bi in 0..num_brailles {
            let mut bits: u32 = 0;
            for col_off in 0..2 {
                let col = bi*2+col_off;
                for (row_off, row) in chunk.iter().enumerate() {
                    let filled = if col < row.len() { row[col] } else { false };
                    if filled {
                        if col_off==0 {
                            match row_off {
                                0 => bits|=0x01,
                                1 => bits|=0x02,
                                2 => bits|=0x04,
                                3 => bits|=0x40,
                                _ => {}
                            }
                        } else {
                            match row_off {
                                0 => bits|=0x08,
                                1 => bits|=0x10,
                                2 => bits|=0x20,
                                3 => bits|=0x80,
                                _ => {}
                            }
                        }
                    }
                }
            }
            brailles.push(char::from_u32(0x2800+bits).unwrap());
        }
        if let Some(pad) = padding {
            if brailles.chars().count() < pad {
                let need = pad - brailles.chars().count();
                brailles.push_str(&" ".repeat(need));
            }
        }
        out_str.push_str(&brailles);
        out_str.push('\n');
        idx += 4;
    }
    out_str.into_bytes()
}
